const pruneEmailDesignVersions = `-- name: PruneEmailDesignVersions :exec
DELETE FROM email_design_versions ev
WHERE ev.workspace_id = $1 AND ev.design_id = $2
  AND ev.version NOT IN (
      SELECT k.version FROM email_design_versions k
      WHERE k.workspace_id = $1 AND k.design_id = $2
      ORDER BY k.version = (
          SELECT max(c.version) FROM email_design_versions c
          WHERE c.workspace_id = $1 AND c.design_id = $2 AND c.reason = 'conflict'
      ) IS TRUE DESC, k.version DESC LIMIT $3)
`

type PruneEmailDesignVersionsParams struct {
	WorkspaceID uuid.UUID
	DesignID    uuid.UUID
	Keep        int32
}

func (q *Queries) PruneEmailDesignVersions(ctx context.Context, arg PruneEmailDesignVersionsParams) error {
	_, err := q.db.Exec(ctx, pruneEmailDesignVersions, arg.WorkspaceID, arg.DesignID, arg.Keep)
	return err
}

